            client=MalformedSqsClient(),
            queue_name="ingestion",
            wait_time_seconds=10,
            visibility_timeout_seconds=30,
            batch_size=1,
        )

        with caplog.at_level(logging.WARNING, logger="ingestion.sqs"):
